import{_ as r,a0 as a,w as o,s as l,I as t,x as i,a1 as d,A as n,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"如何讓網站不下線而從 Redis 2 遷移到 Redis 3 | LCTT x X-CMD","titleTemplate":false,"description":"如何讓網站不下線而從 Redis 2 遷移到 Redis 3 | LCTT (201710) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何讓網站不下線而從 Redis 2 遷移到 Redis 3 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何讓網站不下線而從 Redis 2 遷移到 Redis 3 | LCTT (201710) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201710/20170925 Our journey from Redis 2 to Redis 3 while not taking the site down","title":"如何讓網站不下線而從 Redis 2 遷移到 Redis 3","tag":"201710","desc":""},"relativePath":"201710/20170925 Our journey from Redis 2 to Redis 3 while not taking the site down.md","filePath":"[post].md"}'),R={name:"201710/20170925 Our journey from Redis 2 to Redis 3 while not taking the site down.md"};function m(g,e,u,f,x,T){const s=a("Link");return o(),l("div",null,[e[20]||(e[20]=t("h1",{id:"如何讓網站不下線而從-redis-2-遷移到-redis-3",tabindex:"-1"},[i("如何讓網站不下線而從 Redis 2 遷移到 Redis 3 "),t("a",{class:"header-anchor",href:"#如何讓網站不下線而從-redis-2-遷移到-redis-3","aria-label":"Permalink to “如何讓網站不下線而從 Redis 2 遷移到 Redis 3”"},"​")],-1)),t("p",null,[e[1]||(e[1]=i("我們在 Sky Betting＆Gaming 中使用 ",-1)),d(s,{href:"https://redis.io/"},{default:n(()=>[...e[0]||(e[0]=[i("Redis",-1)])]),_:1}),e[2]||(e[2]=i(" 作為共享內存緩存，用於那些需要跨 API 服務器或者 Web 服務器鑑別令牌之類的操作。在 Core Tribe 內，它用來幫助處理日益龐大的登錄數量，特別是在繁忙的時候，我們在一分鐘內登錄數量會超過 20,000 人。這在很大程度上適用於數據存放在大量服務器的情況下（在 SSO 令牌用於 70 台 Apache HTTPD 服務器的情況下）。我們最近着手升級 Redis 服務器，此升級旨在使用 Redis 3.2 提供的原生集羣功能。這篇Blog希望解釋為什麼我們要使用集羣、我們遇到的問題以及我們的解決方案。",-1))]),e[21]||(e[21]=t("h3",{id:"在開始階段-或至少在升級之前",tabindex:"-1"},[i("在開始階段（或至少在升級之前） "),t("a",{class:"header-anchor",href:"#在開始階段-或至少在升級之前","aria-label":"Permalink to “在開始階段（或至少在升級之前）”"},"​")],-1)),e[22]||(e[22]=t("p",null,[i("我們的傳統緩存中每個緩存都包括一對 Redis 服務器，使用 keepalive 確保始終有一個主節點監聽"),t("ruby",null,[i("浮動 IP "),t("rt",null,"floating IP")]),i("地址。當出現問題時，這些服務器對需要很大的精力來進行管理，而故障模式有時是非常各種各樣的。有時，只允許讀取它所持有的數據，而不允許寫入的從屬節點卻會得到浮動 IP 地址，這種問題是相對容易診斷的，但會讓無論哪個程序試圖使用該緩存時都很麻煩。")],-1)),e[23]||(e[23]=t("h3",{id:"新的應用程序",tabindex:"-1"},[i("新的應用程序 "),t("a",{class:"header-anchor",href:"#新的應用程序","aria-label":"Permalink to “新的應用程序”"},"​")],-1)),t("p",null,[e[4]||(e[4]=i("因此，這種情況下，我們需要構建一個新的應用程序，一個使用",-1)),e[5]||(e[5]=t("ruby",null,[i("共享內存緩存"),t("rt",null,"shared in-memory cache")],-1)),e[6]||(e[6]=i("的應用程序，但是我們不希望對該緩存進行迂迴的故障切換過程。因此，我們的要求是共享的內存緩存，沒有單點故障，可以使用盡可能少的人為干預來應對多種不同的故障模式，並且在事件恢復之後也能夠在很少的人為干預下恢復，一個額外的要求是提高緩存的安全性，以減少數據泄露的範圍（稍後再説）。當時 Redis Sentinel 看起來很有希望，並且有許多程序支持代理 Redis 連接，比如 ",-1)),d(s,{href:"https://github.com/twitter/twemproxy"},{default:n(()=>[...e[3]||(e[3]=[i("twemproxy",-1)])]),_:1}),e[7]||(e[7]=i("。這會導致還要安裝其它很多組件，它應該有效，並且人際交互最少，但它複雜而需要運行大量的服務器和服務，並且相互通信。",-1))]),e[24]||(e[24]=p('<p><img src="http://engineering.skybettingandgaming.com/images/Redis-Sentinel-and-TwemProxy.svg" alt="Redis Sentinel and TwemProxy"></p><p>將會有大量的應用服務器與 twemproxy 進行通信，這會將它們的調用路由到合適的 Redis 主節點，twemproxy 將從 sentinal 集羣獲取主節點的信息，它將控制哪台 Redis 實例是主，哪台是從。這個設置是複雜的，而且仍有單點故障，它依賴於 twemproxy 來處理分片，來連接到正確的 Redis 實例。它具有對應用程序透明的優點，所以我們可以在理論上做到將現有的應用程序轉移到這個 Redis 配置，而不用改變應用程序。但是我們要從頭開始構建一個應用程序，所以遷移應用程序不是一個必需條件。</p><p>幸運的是，這個時候，Redis 3.2 出來了，而且內置了原生集羣，消除了對單一 sentinel 集羣需要。</p><p><img src="http://engineering.skybettingandgaming.com/images/Redis3-Cluster-and-Twemproxy.svg" alt="Redis3 Cluster and Twemproxy"></p><p>它有一個更簡單的設置，但 twemproxy 不支持 Redis 集羣分片，它能為你分片數據，但是如果嘗試在與分片不一致的集羣中這樣做會導致問題。有參考的指南可以使其匹配，但是集羣可以自動改變形式，並改變分片的設置方式。它仍然有單點故障。正是在這一點上，我將永遠感謝我的一位同事發現了一個 Node.js 的 Redis 的集羣發現驅動程序，讓我們完全放棄了 twemproxy。</p><p><img src="http://engineering.skybettingandgaming.com/images/Redis3-Cluster.svg" alt="Redis3 Cluster"></p><p>因此，我們能夠自動分片數據，故障轉移和故障恢復基本上是自動的。應用程序知道哪些節點存在，並且在寫入數據時，如果寫入錯誤的節點，集羣將自動重定向該寫入。這是被選的配置，這讓我們共享的內存緩存相當健壯，可以沒有干預地應付基本的故障模式。在測試期間，我們的確發現了一些缺陷。複製是在一個接一個節點的基礎上進行的，因此如果我們丟失了一個主節點，那麼它的從節點會成為一個單點故障，直到死去的節點恢復服務，也只有主節點對集羣健康投票，所以如果我們一下失去太多主節點，那麼集羣無法自我恢復。但這比我們過去的好。</p><h3 id="向前進" tabindex="-1">向前進 <a class="header-anchor" href="#向前進" aria-label="Permalink to “向前進”">​</a></h3><p>隨着使用集羣 Redis 配置的新程序，我們對於老式 Redis 實例的狀態變得越來越不適應，但是新程序與現有程序的規模並不相同（超過 30GB 的內存專用於我們最大的老式 Redis 實例資料庫）。因此，隨着 Redis 集羣在底層得到了證實，我們決定遷移老式的 Redis 實例到新的 Redis 集羣中。</p><p>由於我們有一個原生支持 Redis 集羣的 Node.js Redis 驅動程序，因此我們開始將 Node.js 程序遷移到 Redis 集羣。但是，如何將數十億字節的數據從一個地方移動到另一個地方，而不會造成重大問題？特別是考慮到這些數據是認證令牌，所以如果它們錯了，我們的終端用户將會被登出。一個選擇是要求網站完全下線，將所有內容都指向新的 Redis 羣集，並將數據遷移到其中，以希望獲得最佳效果。另一個選擇是切換到新集羣，並強制所有用户再次登錄。由於顯而易見的原因，這些都不是非常合適的。我們決定採取的替代方法是將數據同時寫入老式 Redis 實例和正在替換它的集羣，同時隨着時間的推移，我們將逐漸更多地向該集羣讀取。由於數據的有效期有限（令牌在幾個小時後到期），這種方法可以導致零停機，並且不會有數據丟失的風險。所以我們這麼做了。遷移是成功的。</p><p>剩下的就是服務於我們的 PHP 代碼（其中還有一個項目是有用的，其它的最終是沒必要的）的 Redis 的實例了，我們在這過程中遇到了一個困難，實際上是兩個。首先，也是最緊迫的是找到在 PHP 中使用的 Redis 集羣發現驅動程序，還要是我們正在使用的 PHP 版本。這被證明是可行的，因為我們升級到了最新版本的 PHP。我們選擇的驅動程序不喜歡使用 Redis 的授權方式，因此我們決定使用 Redis 集羣作為一個額外的安全步驟 （我告訴你，這將有更多的安全性）。當我們用 Redis 集羣替換每個老式 Redis 實例時，修復似乎很直接，將 Redis 授權關閉，這樣它將會響應所有的請求。然而，這並不是真的，由於某些原因，Redis 集羣不會接受來自 Web 服務器的連接。 Redis 在版本 3 中引入的稱為“保護模式”的新安全功能將在 Redis 綁定到任何接口時將停止監聽來自外部 IP 地址的連接，並無需配置 Redis 授權密碼。這被證明相當容易修復，但讓我們保持警惕。</p><h3 id="現在" tabindex="-1">現在？ <a class="header-anchor" href="#現在" aria-label="Permalink to “現在？”">​</a></h3><p>這就是我們現在的情況。我們已經遷移了我們的一些老式 Redis 實例，並且正在遷移其餘的。我們通過這樣做解決了我們的一些技術債務，並提高了我們的平台的穩定性。使用 Redis 集羣，我們還可以擴展內存資料庫並擴展它們。 Redis 是單線程的，所以只要在單個實例中留出更多的內存就會可以得到這麼多的增長，而且我們已經緊跟在這個限制後面。我們期待着從新的集羣中獲得改進的性能，同時也為我們提供了擴展和負載均衡的更多選擇。</p><h3 id="未來怎麼樣" tabindex="-1">未來怎麼樣？ <a class="header-anchor" href="#未來怎麼樣" aria-label="Permalink to “未來怎麼樣？”">​</a></h3><p>我們解決了一些技術性債務，這使我們的服務更容易支持，更加穩定。但這並不意味着這項工作完成了，Redis 4 似乎有一些我們可能想要研究的功能。而且 Redis 並不是我們使用的唯一軟件。我們將繼續努力改進平台，縮短處理技術債務的時間，但隨着客户羣體的擴大，我們力求提供更豐富的服務，我們總是會遇到需要改進的事情。下一個挑戰可能與每分鐘超過 20,000次 登錄到超過 40,000 次甚至更高的擴展有關。</p><hr>',16)),t("p",null,[e[9]||(e[9]=i("via: ",-1)),d(s,{href:"http://engineering.skybettingandgaming.com/2017/09/25/redis-2-to-redis-3/"},{default:n(()=>[...e[8]||(e[8]=[i("http://engineering.skybettingandgaming.com/2017/09/25/redis-2-to-redis-3/",-1)])]),_:1})]),t("p",null,[e[12]||(e[12]=i("作者：",-1)),d(s,{href:"http://engineering.skybettingandgaming.com/authors#craig_stewart"},{default:n(()=>[...e[10]||(e[10]=[i("Craig Stewart",-1)])]),_:1}),e[13]||(e[13]=i(" 譯者：",-1)),d(s,{href:"https://github.com/geekpi"}),e[14]||(e[14]=i(" 校對：",-1)),d(s,{href:"https://github.com/wxy"},{default:n(()=>[...e[11]||(e[11]=[i("wxy",-1)])]),_:1})]),t("p",null,[e[17]||(e[17]=i("本文由 ",-1)),d(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[15]||(e[15]=[i("LCTT",-1)])]),_:1}),e[18]||(e[18]=i(" 原創編譯，",-1)),d(s,{href:"https://linux.cn/"},{default:n(()=>[...e[16]||(e[16]=[i("Linux中國",-1)])]),_:1}),e[19]||(e[19]=i(" 榮譽推出",-1))])])}const w=r(R,[["render",m]]);export{P as __pageData,w as default};
